class Account {
    private final String accountId;
    private BigDecimal balance;
    Account(String id, BigDecimal bal) { accountId=id; balance=bal; }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be AccountMatcher.java in a real project ───
class AccountMatcher {
    private static final Logger log = Logger.getLogger("BankLog");

    void matchAccountId(String a, String b) {
        boolean wrong = (a == b);            // compares references
        boolean right = a.equals(b);         // compares content
        log.warning(() -> "ID  == gives " + wrong + " (unreliable)");
        log.info(() -> "ID  .equals gives " + right + " (correct)");
    }

    // For money, equals() is also strict about scale: 50000 vs 50000.00 are NOT equals()
    // but ARE equal by compareTo. compareTo is the correct value check for money.
    void matchAmount(BigDecimal a, BigDecimal b) {
        boolean byEquals = a.equals(b);          // false: different scale
        boolean byCompare = a.compareTo(b) == 0; // true: same numeric value
        log.warning(() -> "Money .equals gives " + byEquals + " (scale-sensitive)");
        log.info(() -> "Money compareTo==0 gives " + byCompare + " (correct for value)");
    }
}
